    /// <summary>
    /// Check whether a localization item exists in the current locale.
    /// </summary>
    /// <param name="id">The key of the localized item you want to test.</param>
    /// <returns>True if the item exists in the current locale; otherwise false.</returns>
    public bool IsItemExist(string id, IEqualityComparer<string>? comparer = null) => _LocalizedItems_.Contains(id, comparer ?? StringComparer.Ordinal);
    
